    #[test]
    fn oracle_successful_statement_clears_late_cancel_protection() {
        let statement_effects =
            crate::db::statement_session_post_processor_for(crate::db::DatabaseType::Oracle)
                .effects_for_sql("INSERT INTO t VALUES (1)");
        for auto_commit in [true, false] {
            let (sender, _receiver) = progress_channel();
            let mut cleanup = new_test_cleanup_guard(
                sender,
                Arc::new(Mutex::new(None)),
                Arc::new(Mutex::new(None)),
                Arc::new(Mutex::new(true)),
                Arc::new(Mutex::new(true)),
            );
            cleanup.protect_oracle_statement_on_cancel(auto_commit, statement_effects);

            assert_eq!(
                cleanup.oracle_pooled_session_invalidated_on_cancel,
                auto_commit
            );
            assert_eq!(
                cleanup.oracle_pooled_session_transaction_decision_on_cancel,
                !auto_commit
            );

            cleanup.clear_oracle_successful_statement_cancel_protection();

            assert!(
                !cleanup.oracle_pooled_session_invalidated_on_cancel,
                "successful auto-commit statement should not discard on a late cancel"
            );
            assert!(
                !cleanup.oracle_pooled_session_transaction_decision_on_cancel,
                "successful manual-commit statement should not require a decision only because cancel was clicked late"
            );
        }
    }

