    #[test]
    fn oracle_implicit_commit_clears_prior_decision_required() {
        // Regression: a prior DML had set `transaction_decision_required`.
        // A subsequent DDL with implicit commit (or a successful explicit
        // COMMIT/ROLLBACK / auto-commit) routes through
        // `clear_oracle_pooled_session_maybe_dirty`, which must also drop the
        // decision flag — otherwise the cleanup guard re-stores the lease as
        // `requires_transaction_decision = true` and the user is forced to
        // commit/rollback an already-committed transaction.
        let (sender, _receiver) = progress_channel();
        let mut cleanup = new_test_cleanup_guard(
            sender,
            Arc::new(Mutex::new(None)),
            Arc::new(Mutex::new(None)),
            Arc::new(Mutex::new(false)),
            Arc::new(Mutex::new(true)),
        );

        cleanup.require_oracle_pooled_session_transaction_decision();
        cleanup.mark_oracle_pooled_session_maybe_dirty();
        assert!(cleanup.oracle_pooled_session_transaction_decision_required);
        assert!(cleanup.oracle_pooled_session_forced_maybe_dirty);

        cleanup.clear_oracle_pooled_session_maybe_dirty();
        assert!(!cleanup.oracle_pooled_session_transaction_decision_required);
        assert!(!cleanup.oracle_pooled_session_forced_maybe_dirty);
    }

