    #[test]
    #[ignore = "requires local Oracle database via ORACLE_TEST_* environment variables"]
    fn oracle_live_result_routes_monitor_each_result_tab() {
        let Some((_connection, conn)) = oracle_test_connection() else {
            return;
        };
        let session = Arc::new(Mutex::new(SessionState {
            db_type: DatabaseType::Oracle,
            ..SessionState::default()
        }));

        let (script_sender, script_receiver) = progress_channel();
        SqlEditorWidget::emit_script_output(
            &script_sender,
            &session,
            vec!["ORACLE_ROUTE_SCRIPT".to_string()],
        );
        let script_event = script_receiver
            .recv_timeout(Duration::from_secs(5))
            .expect("Oracle script output route event should arrive");
        assert_result_routes_only(
            "Oracle script transcript must route only to Script Output",
            &script_event,
            &[ResultPaneRoute::ScriptOutput],
        );

        {
            let mut guard = session
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner());
            guard.server_output.enabled = true;
            guard.server_output.size = 0;
        }
        QueryExecutor::enable_dbms_output(conn.as_ref(), None)
            .expect("enable Oracle DBMS_OUTPUT for route monitor");
        conn.execute("BEGIN DBMS_OUTPUT.PUT_LINE('ORACLE_ROUTE_DBMS'); END;", &[])
            .expect("write Oracle DBMS_OUTPUT route marker");
        let (dbms_sender, dbms_receiver) = progress_channel();
        let mut result_index = 0usize;
        SqlEditorWidget::emit_dbms_output(
            &dbms_sender,
            "ORACLE_TEST",
            conn.as_ref(),
            &session,
            &mut result_index,
        )
        .expect("Oracle DBMS_OUTPUT route event should be emitted");
        let dbms_event = dbms_receiver
            .recv_timeout(Duration::from_secs(5))
            .expect("Oracle DBMS output route event should arrive");
        assert_result_routes_only(
            "Oracle DBMS output must route only to DBMS Output",
            &dbms_event,
            &[ResultPaneRoute::DbmsOutput],
        );

        let select_result = QueryExecutor::execute(
            conn.as_ref(),
            "SELECT 'ORACLE_ROUTE_GRID' AS marker FROM dual",
        )
        .expect("Oracle SELECT route monitor query should succeed");
        let select_event = QueryProgress::StatementFinished {
            index: 0,
            result: select_result,
            connection_name: "ORACLE_TEST".to_string(),
            timed_out: false,
        };
        assert_result_routes_only(
            "Oracle SELECT completion must route only to Data Grid plus Messages Info",
            &select_event,
            &[ResultPaneRoute::DataGrid, ResultPaneRoute::MessagesInfo],
        );

        let _ = conn.execute("DROP TABLE qt_result_route_monitor PURGE", &[]);
        let ddl_result = QueryExecutor::execute(
            conn.as_ref(),
            "CREATE TABLE qt_result_route_monitor (id NUMBER)",
        )
        .expect("Oracle DDL route monitor statement should succeed");
        let ddl_event = QueryProgress::StatementFinished {
            index: 1,
            result: ddl_result,
            connection_name: "ORACLE_TEST".to_string(),
            timed_out: false,
        };
        assert_result_routes_only(
            "Oracle non-select success must route only to Messages Info",
            &ddl_event,
            &[ResultPaneRoute::MessagesInfo],
        );
        let _ = conn.execute("DROP TABLE qt_result_route_monitor PURGE", &[]);

        let error_result =
            match QueryExecutor::execute(conn.as_ref(), "SELECT * FROM qt_result_route_missing") {
                Ok(result) => panic!(
                    "Oracle missing-table route monitor should fail, got success: {}",
                    result.message
                ),
                Err(err) => QueryResult::new_error(
                    "SELECT * FROM qt_result_route_missing",
                    &err.to_string(),
                ),
            };
        let error_event = QueryProgress::StatementFinished {
            index: 2,
            result: error_result,
            connection_name: "ORACLE_TEST".to_string(),
            timed_out: false,
        };
        assert_result_routes_only(
            "Oracle SQL errors must route only to Messages Errors",
            &error_event,
            &[ResultPaneRoute::MessagesErrors],
        );

        let plan = QueryExecutor::get_explain_plan(
            conn.as_ref(),
            "SELECT 'ORACLE_ROUTE_EXPLAIN' AS marker FROM dual",
        )
        .expect("Oracle explain plan route monitor should succeed");
        let explain_event = QueryProgress::ExplainPlanOutput {
            result: SqlEditorWidget::build_explain_plan_result(
                &crate::ui::explain_plan::ExplainPlanData::Tree(
                    crate::ui::explain_plan::oracle_plan_nodes(&plan),
                ),
            ),
        };
        assert_result_routes_only(
            "Oracle explain output must route to Data Grid as a new explain tab",
            &explain_event,
            &[ResultPaneRoute::DataGrid],
        );
    }

    #[test]
    #[ignore = "requires local Oracle database via ORACLE_TEST_* environment variables"]
    fn oracle_cleanup_marks_transaction_state_but_keeps_tab_session_after_rollback() {
        let Some((_connection, conn)) = oracle_test_connection() else {
            return;
        };
        let _ = conn.execute("DROP TABLE qt_oracle_session_rule PURGE", &[]);
        conn.execute("CREATE TABLE qt_oracle_session_rule (id NUMBER)", &[])
            .expect("create Oracle session-rule table");
        conn.commit().expect("commit Oracle session-rule setup");

        assert!(!SqlEditorWidget::oracle_session_may_have_uncommitted_work(
            conn.as_ref(),
            "oracle session-rule initial probe"
        ));
        conn.execute("INSERT INTO qt_oracle_session_rule (id) VALUES (1)", &[])
            .expect("insert Oracle session-rule row");
        assert!(SqlEditorWidget::oracle_session_may_have_uncommitted_work(
            conn.as_ref(),
            "oracle session-rule DML probe"
        ));

        let pooled_db_session = crate::db::SharedDbSessionLease::new();
        {
            let (sender, _receiver) = progress_channel();
            let mut cleanup = new_test_cleanup_guard(
                sender,
                Arc::new(Mutex::new(None)),
                Arc::new(Mutex::new(None)),
                Arc::new(Mutex::new(false)),
                Arc::new(Mutex::new(true)),
            );
            cleanup.track_oracle_pooled_session(
                pooled_db_session.clone(),
                7,
                0,
                Arc::clone(&conn),
                RetainedSessionState::default(),
            );
        }

        let snapshot = pooled_db_session
            .snapshot()
            .expect("open Oracle transaction should retain a pooled session");
        assert_eq!(snapshot.db_type, DatabaseType::Oracle);
        assert_eq!(
            snapshot.transaction_state,
            TransactionSessionState::MaybeDirty
        );
        assert!(
            snapshot.transaction_state.may_have_uncommitted_work(),
            "open Oracle transaction should be visible as retained session state"
        );

        conn.rollback()
            .expect("rollback Oracle retained transaction");
        pooled_db_session.clear();
        {
            let (sender, _receiver) = progress_channel();
            let mut cleanup = new_test_cleanup_guard(
                sender,
                Arc::new(Mutex::new(None)),
                Arc::new(Mutex::new(None)),
                Arc::new(Mutex::new(false)),
                Arc::new(Mutex::new(true)),
            );
            cleanup.track_oracle_pooled_session(
                pooled_db_session.clone(),
                7,
                0,
                Arc::clone(&conn),
                RetainedSessionState::default(),
            );
        }
        let snapshot = pooled_db_session
            .snapshot()
            .expect("rolled back Oracle transaction should keep the tab pooled session");
        assert_eq!(snapshot.db_type, DatabaseType::Oracle);
        assert!(
            !snapshot.transaction_state.may_have_uncommitted_work(),
            "rolled back Oracle transaction should not be marked as transaction state"
        );

        let _ = conn.execute("DROP TABLE qt_oracle_session_rule PURGE", &[]);
    }

