    #[test]
    fn lazy_fetch_cancel_watchdog_forces_close_and_clears_handle() {
        let (command_sender, command_receiver) = mpsc::channel();
        let (progress_sender, progress_receiver) = progress_channel();
        let db_cancel_called = Arc::new(AtomicBool::new(false));
        let status_activity = crate::db::DbActivityGuard::untracked_for_test();
        let active = Arc::new(Mutex::new(Some(LazyFetchHandle {
            index: 3,
            session_id: 42,
            operation_id: 42,
            connection_generation: 7,
            connection_id: None,
            db_type: crate::db::DatabaseType::Oracle,
            sender: command_sender,
            cancel_handle: Some(LazyFetchCancelHandle::Test(db_cancel_called.clone())),
            cancel_requested: Arc::new(AtomicBool::new(true)),
            retain_session_on_cancel: Arc::new(AtomicBool::new(true)),
            db_cancel_requested: Arc::new(AtomicBool::new(true)),
            fetch_in_progress: Arc::new(AtomicBool::new(true)),
            cancel_watchdog_started: Arc::new(AtomicBool::new(false)),
            status_activity: Some(status_activity.finish_handle()),
        })));

        SqlEditorWidget::start_lazy_fetch_cancel_watchdog_with(
            active.clone(),
            progress_sender,
            42,
            Duration::from_millis(1),
        )
        .expect("lazy fetch cancel watchdog should start");

        let event = progress_receiver
            .recv_timeout(Duration::from_secs(1))
            .expect("watchdog should emit lazy close");
        assert!(!SqlEditorWidget::lazy_fetch_handle_matches(&active, 42));
        assert!(matches!(
            command_receiver.recv_timeout(Duration::from_secs(1)),
            Ok(LazyFetchCommand::ForceCancel)
        ));
        for _ in 0..20 {
            if db_cancel_called.load(Ordering::Relaxed) {
                break;
            }
            std::thread::sleep(Duration::from_millis(5));
        }
        assert!(db_cancel_called.load(Ordering::Relaxed));
        assert!(status_activity.is_finished());
        assert!(matches!(
            event,
            QueryProgress::LazyFetchClosed {
                index: 3,
                session_id: 42,
                operation_id: 42,
                connection_generation: 7,
                cancelled: true,
                cursor_closed: false,
                fetch_worker_done: false,
                error_kind: InterruptKind::UnsafeOrUnknown,
            }
        ));
    }

    #[test]
    fn repeated_lazy_fetch_cancel_starts_only_one_force_watchdog() {
        let (command_sender, command_receiver) = mpsc::channel();
        let (progress_sender, progress_receiver) = progress_channel();
        let force_started = Arc::new(AtomicBool::new(false));
        let force_release = Arc::new(AtomicBool::new(false));
        let watchdog_started = Arc::new(AtomicBool::new(false));
        let active = Arc::new(Mutex::new(Some(LazyFetchHandle {
            index: 3,
            session_id: 42,
            operation_id: 42,
            connection_generation: 7,
            connection_id: None,
            db_type: crate::db::DatabaseType::Oracle,
            sender: command_sender,
            cancel_handle: Some(LazyFetchCancelHandle::TestBlockingForce {
                started: force_started.clone(),
                release: force_release.clone(),
            }),
            cancel_requested: Arc::new(AtomicBool::new(true)),
            retain_session_on_cancel: Arc::new(AtomicBool::new(true)),
            db_cancel_requested: Arc::new(AtomicBool::new(true)),
            fetch_in_progress: Arc::new(AtomicBool::new(true)),
            cancel_watchdog_started: watchdog_started.clone(),
            status_activity: None,
        })));

        SqlEditorWidget::start_lazy_fetch_cancel_watchdog_with(
            active.clone(),
            progress_sender.clone(),
            42,
            Duration::from_millis(1),
        )
        .expect("first lazy fetch cancel watchdog should start");
        SqlEditorWidget::start_lazy_fetch_cancel_watchdog_with(
            active.clone(),
            progress_sender,
            42,
            Duration::from_millis(1),
        )
        .expect("repeated lazy fetch cancel should reuse the active watchdog");

        assert!(matches!(
            command_receiver.recv_timeout(Duration::from_secs(1)),
            Ok(LazyFetchCommand::ForceCancel)
        ));
        for _ in 0..100 {
            if force_started.load(Ordering::Relaxed) {
                break;
            }
            std::thread::sleep(Duration::from_millis(5));
        }
        assert!(force_started.load(Ordering::Relaxed));
        assert!(command_receiver
            .recv_timeout(Duration::from_millis(50))
            .is_err());
        assert!(progress_receiver
            .recv_timeout(Duration::from_millis(50))
            .is_err());

        force_release.store(true, Ordering::Relaxed);
        assert!(matches!(
            progress_receiver.recv_timeout(Duration::from_secs(1)),
            Ok(QueryProgress::LazyFetchClosed { session_id: 42, .. })
        ));
        assert!(!SqlEditorWidget::lazy_fetch_handle_matches(&active, 42));
        for _ in 0..100 {
            if !watchdog_started.load(Ordering::Acquire) {
                break;
            }
            std::thread::sleep(Duration::from_millis(5));
        }
        assert!(!watchdog_started.load(Ordering::Acquire));
    }

    #[test]
    fn lazy_fetch_force_failure_releases_watchdog_before_retryable_event() {
        let (command_sender, command_receiver) = mpsc::channel();
        let (progress_sender, progress_receiver) = progress_channel();
        let watchdog_started = Arc::new(AtomicBool::new(false));
        let active = Arc::new(Mutex::new(Some(LazyFetchHandle {
            index: 3,
            session_id: 42,
            operation_id: 42,
            connection_generation: 7,
            connection_id: None,
            db_type: crate::db::DatabaseType::MySQL,
            sender: command_sender,
            // A GENUINE failure: the fetch has no force-cancel handle at all
            // and does not stop. An empty `QueryCancelTarget` used to stand in
            // for one, but a target with nothing published is the WITHDRAW
            // answering, not a cancel that failed -- see
            // `lazy_fetch_force_on_a_withdrawn_target_is_not_a_failure`.
            cancel_handle: None,
            cancel_requested: Arc::new(AtomicBool::new(true)),
            retain_session_on_cancel: Arc::new(AtomicBool::new(false)),
            db_cancel_requested: Arc::new(AtomicBool::new(true)),
            fetch_in_progress: Arc::new(AtomicBool::new(true)),
            cancel_watchdog_started: watchdog_started.clone(),
            status_activity: None,
        })));

        SqlEditorWidget::start_lazy_fetch_cancel_watchdog_with(
            active.clone(),
            progress_sender,
            42,
            Duration::from_millis(1),
        )
        .expect("lazy fetch cancel watchdog should start");

        assert!(matches!(
            command_receiver.recv_timeout(Duration::from_secs(1)),
            Ok(LazyFetchCommand::ForceCancel)
        ));
        assert!(matches!(
            progress_receiver.recv_timeout(Duration::from_secs(3)),
            Ok(QueryProgress::LazyFetchCancelFailed { session_id: 42, .. })
        ));
        assert!(SqlEditorWidget::lazy_fetch_handle_matches(&active, 42));
        assert!(
            !watchdog_started.load(Ordering::Acquire),
            "a retry must be able to claim a new lazy-fetch watchdog before failure is published"
        );
    }

    /// A lazy fetch that gave its session back before the force tier could land
    /// is not a cancel that FAILED.
    ///
    /// This road is the reason the answer is a type. The operation road
    /// recognised a withdraw by comparing an error STRING and returned quietly;
    /// this one never learned the rule, so the user was told "Cancel failed:
    /// the session this cancel was published for has already been handed back"
    /// and invited to retry a tear-down that must never happen.
    #[test]
    fn lazy_fetch_force_on_a_withdrawn_target_is_not_a_failure() {
        let (command_sender, command_receiver) = mpsc::channel();
        let (progress_sender, progress_receiver) = progress_channel();
        let watchdog_started = Arc::new(AtomicBool::new(false));
        let target = QueryCancelTarget::empty();
        target.publish(QueryCancelHandle::Test(Arc::new(AtomicBool::new(false))));
        let active = Arc::new(Mutex::new(Some(LazyFetchHandle {
            index: 3,
            session_id: 42,
            operation_id: 42,
            connection_generation: 7,
            connection_id: None,
            db_type: crate::db::DatabaseType::MySQL,
            sender: command_sender,
            cancel_handle: Some(target.as_handle()),
            cancel_requested: Arc::new(AtomicBool::new(true)),
            retain_session_on_cancel: Arc::new(AtomicBool::new(false)),
            db_cancel_requested: Arc::new(AtomicBool::new(true)),
            fetch_in_progress: Arc::new(AtomicBool::new(true)),
            cancel_watchdog_started: watchdog_started.clone(),
            status_activity: None,
        })));
        // The release door withdraws BEFORE the session moves; here that lands
        // while the watchdog is on its way to the force tier.
        target.withdraw();

        SqlEditorWidget::start_lazy_fetch_cancel_watchdog_with(
            active.clone(),
            progress_sender,
            42,
            Duration::from_millis(1),
        )
        .expect("lazy fetch cancel watchdog should start");

        assert!(matches!(
            command_receiver.recv_timeout(Duration::from_secs(1)),
            Ok(LazyFetchCommand::ForceCancel)
        ));
        assert!(
            progress_receiver
                .recv_timeout(Duration::from_secs(2))
                .is_err(),
            "a withdrawn target must not be reported to the user as a cancel that failed"
        );
    }

