    #[test]
    fn mariadb_lazy_select_uses_mariadb_execution_context_effects() {
        let post_processor = crate::db::statement_session_post_processor_for(DatabaseType::MariaDB);
        let pending = crate::db::retained_session_state_after_statement(
            post_processor,
            RetainedSessionState::default(),
            post_processor.effects_for_sql("SET TRANSACTION ISOLATION LEVEL SERIALIZABLE"),
            false,
            false,
            false,
            false,
        );
        assert!(pending.has_only_next_transaction_mode_override());

        let sql = "SET STATEMENT max_statement_time=1 FOR SELECT 1";
        let effects = SqlEditorWidget::mysql_lazy_select_statement_effects_for_execution_context(
            DatabaseType::MariaDB,
            sql,
            true,
            post_processor.effects_for_sql(sql),
        );
        let retained = SqlEditorWidget::mysql_retained_session_state_after_statement_from_probe(
            DatabaseType::MariaDB,
            pending,
            sql,
            effects,
            true,
            false,
            crate::db::TransactionProbeResult {
                may_have_uncommitted_work: false,
                used_fallback: false,
            },
            false,
        );

        assert!(
            !retained.may_have_transaction_mode_override(),
            "MariaDB lazy SET STATEMENT SELECT should consume pending next-transaction mode"
        );
        assert!(!retained.requires_physical_session_preservation());
    }

