    #[test]
    fn mysql_session_state_hints_preserve_manual_transaction_until_commit() {
        let start_hint = SqlEditorWidget::mysql_session_state_hint_for_sql("START TRANSACTION");
        assert!(!start_hint.clears_session_state);
        assert!(start_hint.may_leave_session_bound_state);
        assert!(!start_hint.may_hold_session_lock);
        assert!(start_hint.requires_retention_when_autocommit_off);

        let select_hint = SqlEditorWidget::mysql_session_state_hint_for_sql("SELECT 1");
        assert!(!select_hint.clears_session_state);
        assert!(!select_hint.may_leave_session_bound_state);
        assert!(!select_hint.may_hold_session_lock);
        assert!(!select_hint.requires_retention_when_autocommit_off);

        let commit_hint = SqlEditorWidget::mysql_session_state_hint_for_sql("COMMIT");
        assert!(commit_hint.clears_session_state);
        assert!(!commit_hint.may_leave_session_bound_state);

        let commit_no_chain_hint =
            SqlEditorWidget::mysql_session_state_hint_for_sql("COMMIT AND NO CHAIN");
        assert!(commit_no_chain_hint.clears_session_state);
        assert!(!commit_no_chain_hint.requires_transaction_decision_after_success);

        let commit_with_option_hint =
            SqlEditorWidget::mysql_session_state_hint_for_sql("COMMIT AND CHAIN");
        assert!(!commit_with_option_hint.clears_session_state);
        assert!(commit_with_option_hint.may_leave_session_bound_state);

        let rollback_chain_hint =
            SqlEditorWidget::mysql_session_state_hint_for_sql("ROLLBACK WORK AND CHAIN");
        assert!(!rollback_chain_hint.clears_session_state);
        assert!(rollback_chain_hint.may_leave_session_bound_state);

        let rollback_to_hint =
            SqlEditorWidget::mysql_session_state_hint_for_sql("ROLLBACK TO SAVEPOINT sp1");
        assert!(!rollback_to_hint.clears_session_state);
        assert!(rollback_to_hint.may_leave_session_bound_state);
        assert!(rollback_to_hint.requires_retention_when_autocommit_off);
        assert!(!rollback_to_hint.requires_transaction_decision_after_success);

        let rollback_work_to_hint =
            SqlEditorWidget::mysql_session_state_hint_for_sql("ROLLBACK WORK TO SAVEPOINT sp1");
        assert!(!rollback_work_to_hint.clears_session_state);
        assert!(rollback_work_to_hint.may_leave_session_bound_state);
        assert!(rollback_work_to_hint.requires_retention_when_autocommit_off);
        assert!(!rollback_work_to_hint.requires_transaction_decision_after_success);

        let release_commit_hint =
            SqlEditorWidget::mysql_session_state_hint_for_sql("COMMIT RELEASE");
        assert!(release_commit_hint.clears_session_state);
        assert!(!release_commit_hint.requires_transaction_decision_after_success);
        assert!(
            SqlEditorWidget::mysql_statement_session_effects_for_sql("COMMIT RELEASE")
                .releases_physical_session()
        );
        assert!(
            !SqlEditorWidget::mysql_statement_session_effects_for_sql("COMMIT NO RELEASE")
                .releases_physical_session()
        );

        let unknown_commit_hint = SqlEditorWidget::mysql_session_state_hint_for_sql("COMMIT WAT");
        assert!(!unknown_commit_hint.clears_session_state);
        assert!(unknown_commit_hint.may_leave_session_bound_state);
        assert!(unknown_commit_hint.requires_transaction_decision_after_success);

        let invalid_autocommit_hint =
            SqlEditorWidget::mysql_session_state_hint_for_sql("SET AUTOCOMMIT = MAYBE");
        assert!(!invalid_autocommit_hint.clears_session_state);
        assert!(invalid_autocommit_hint.may_leave_session_bound_state);
        assert!(invalid_autocommit_hint.requires_transaction_decision_after_success);
        assert!(invalid_autocommit_hint.changes_auto_commit);

        let session_var_autocommit_hint =
            SqlEditorWidget::mysql_session_state_hint_for_sql("SET @@session.autocommit = 0");
        assert!(session_var_autocommit_hint.changes_auto_commit);
        assert!(!session_var_autocommit_hint.clears_session_state);

        let second_assignment_autocommit_hint =
            SqlEditorWidget::mysql_session_state_hint_for_sql("SET sql_notes = 0, autocommit = 0");
        assert!(second_assignment_autocommit_hint.changes_auto_commit);
        assert!(!second_assignment_autocommit_hint.clears_session_state);

        let load_hint = SqlEditorWidget::mysql_session_state_hint_for_sql(
            "LOAD DATA LOCAL INFILE 'data.csv' INTO TABLE t",
        );
        assert!(load_hint.may_leave_session_bound_state);
        assert!(load_hint.requires_retention_when_autocommit_off);
    }

    #[test]
    fn mysql_session_state_hints_cover_implicit_commit_and_session_state() {
        let ddl_hint = SqlEditorWidget::mysql_session_state_hint_for_sql("CREATE TABLE t (id INT)");
        assert!(ddl_hint.clears_session_state);
        assert!(!ddl_hint.may_leave_session_bound_state);

        let temp_hint =
            SqlEditorWidget::mysql_session_state_hint_for_sql("CREATE TEMPORARY TABLE t (id INT)");
        assert!(!temp_hint.clears_session_state);
        assert!(temp_hint.may_leave_session_bound_state);
        assert!(!temp_hint.requires_retention_when_autocommit_off);

        let drop_temp_hint =
            SqlEditorWidget::mysql_session_state_hint_for_sql("DROP TEMPORARY TABLE t");
        assert!(!drop_temp_hint.clears_session_state);
        assert!(!drop_temp_hint.may_leave_session_bound_state);

        let lock_hint = SqlEditorWidget::mysql_session_state_hint_for_sql("LOCK TABLES t WRITE");
        assert!(lock_hint.clears_session_state);
        assert!(lock_hint.may_leave_session_bound_state);
        assert!(lock_hint.may_hold_session_lock);
        assert!(lock_hint.requires_retention_when_autocommit_off);

        let get_lock_hint =
            SqlEditorWidget::mysql_session_state_hint_for_sql("SELECT GET_LOCK('x', 1)");
        assert!(!get_lock_hint.clears_session_state);
        assert!(get_lock_hint.may_leave_session_bound_state);
        assert!(get_lock_hint.may_hold_session_lock);
        assert!(get_lock_hint.requires_retention_when_autocommit_off);

        let select_into_hint =
            SqlEditorWidget::mysql_session_state_hint_for_sql("SELECT COUNT(*) INTO @cnt FROM t");
        assert!(!select_into_hint.clears_session_state);
        assert!(select_into_hint.may_leave_session_bound_state);
        assert!(!select_into_hint.requires_retention_when_autocommit_off);

        let select_assign_hint =
            SqlEditorWidget::mysql_session_state_hint_for_sql("SELECT @cnt := COUNT(*) FROM t");
        assert!(!select_assign_hint.clears_session_state);
        assert!(select_assign_hint.may_leave_session_bound_state);
        assert!(!select_assign_hint.requires_retention_when_autocommit_off);

        let prepare_hint =
            SqlEditorWidget::mysql_session_state_hint_for_sql("PREPARE stmt FROM @sql");
        assert!(!prepare_hint.clears_session_state);
        assert!(prepare_hint.may_leave_session_bound_state);
        assert!(!prepare_hint.requires_retention_when_autocommit_off);

        let insert_hint =
            SqlEditorWidget::mysql_session_state_hint_for_sql("INSERT INTO t VALUES (1)");
        assert!(!insert_hint.clears_session_state);
        assert!(insert_hint.may_leave_session_bound_state);
        assert!(insert_hint.requires_retention_when_autocommit_off);

        let autocommit_on_hint =
            SqlEditorWidget::mysql_session_state_hint_for_sql("SET SESSION autocommit = 1");
        assert!(autocommit_on_hint.clears_session_state);
        assert!(!autocommit_on_hint.may_leave_session_bound_state);
        assert!(!autocommit_on_hint.requires_retention_when_autocommit_off);
        assert!(autocommit_on_hint.changes_auto_commit);

        let grant_hint =
            SqlEditorWidget::mysql_session_state_hint_for_sql("GRANT SELECT ON db.* TO 'u'@'%'");
        assert!(grant_hint.clears_session_state);
        assert!(!grant_hint.may_leave_session_bound_state);
    }

    #[test]
    fn mysql_explicit_cancel_reuses_only_plain_select_like_sessions() {
        let select_hint = SqlEditorWidget::mysql_session_state_hint_for_sql("SELECT 1");
        assert!(crate::db::statement_cancel_can_reuse_session(select_hint));
        let with_select_hint = SqlEditorWidget::mysql_session_state_hint_for_sql(
            "WITH q AS (SELECT 1 AS id) SELECT id FROM q",
        );
        assert!(crate::db::statement_cancel_can_reuse_session(
            with_select_hint
        ));

        for sql in [
            "INSERT INTO t VALUES (1)",
            "WITH q AS (SELECT 1 AS id) INSERT INTO t SELECT id FROM q",
            "CREATE TABLE t (id INT)",
            "BEGIN",
            "CALL p_write()",
            "LOCK TABLES t WRITE",
            "SELECT GET_LOCK('x', 1)",
            "SELECT COUNT(*) INTO @cnt FROM t",
            "SELECT @cnt := COUNT(*) FROM t",
            "SET @x = 1",
        ] {
            let hint = SqlEditorWidget::mysql_session_state_hint_for_sql(sql);
            assert!(
                !crate::db::statement_cancel_can_reuse_session(hint),
                "cancel should not reuse potentially dirty session for: {sql}"
            );
        }
    }

    #[test]
    fn mysql_batch_lock_hints_track_table_and_named_locks_separately() {
        let mut batch_effects = crate::db::MySqlBatchSessionEffects::default();

        SqlEditorWidget::mysql_batch_session_state_hint_for_sql(
            "LOCK TABLES t WRITE",
            true,
            &mut batch_effects,
        );
        assert!(batch_effects.may_hold_table_lock());
        assert!(!batch_effects.may_hold_named_lock());

        SqlEditorWidget::mysql_batch_session_state_hint_for_sql(
            "UNLOCK TABLES",
            true,
            &mut batch_effects,
        );
        assert!(!batch_effects.may_hold_table_lock());

        SqlEditorWidget::mysql_batch_session_state_hint_for_sql(
            "SELECT GET_LOCK('qt_lock_a', 0)",
            true,
            &mut batch_effects,
        );
        assert!(batch_effects.may_hold_named_lock());
        assert!(!batch_effects.saw_uncertain_named_lock_release());

        SqlEditorWidget::mysql_batch_session_state_hint_for_sql(
            "SELECT RELEASE_LOCK('qt_lock_a')",
            true,
            &mut batch_effects,
        );
        assert!(
            batch_effects.may_hold_named_lock(),
            "single RELEASE_LOCK may fail or leave other named locks held"
        );
        assert!(batch_effects.saw_uncertain_named_lock_release());

        SqlEditorWidget::mysql_batch_session_state_hint_for_sql(
            "SELECT RELEASE_ALL_LOCKS()",
            true,
            &mut batch_effects,
        );
        assert!(!batch_effects.may_hold_named_lock());
        assert!(!batch_effects.saw_uncertain_named_lock_release());
    }

    #[test]
    fn mysql_batch_implicit_commit_hints_update_dirty_state() {
        let mut batch_effects = crate::db::MySqlBatchSessionEffects::default();

        SqlEditorWidget::mysql_batch_session_state_hint_for_sql(
            "WITH q AS (SELECT 1 AS id) SELECT id FROM q",
            false,
            &mut batch_effects,
        );
        assert!(
            !batch_effects.may_have_uncommitted_work(),
            "read-only WITH SELECT should not dirty an autocommit-off batch"
        );

        SqlEditorWidget::mysql_batch_session_state_hint_for_sql(
            "INSERT INTO t VALUES (1)",
            false,
            &mut batch_effects,
        );
        assert!(batch_effects.may_have_uncommitted_work());

        SqlEditorWidget::mysql_batch_session_state_hint_for_sql(
            "CREATE TABLE ddl_commits_prior_work (id INT)",
            false,
            &mut batch_effects,
        );
        assert!(
            !batch_effects.may_have_uncommitted_work(),
            "implicit-commit DDL should clear the batch dirty flag after success candidates"
        );

        SqlEditorWidget::mysql_batch_session_state_hint_for_sql(
            "INSERT INTO t VALUES (2)",
            false,
            &mut batch_effects,
        );
        assert!(batch_effects.may_have_uncommitted_work());

        SqlEditorWidget::mysql_batch_session_state_hint_for_sql(
            "DROP TEMPORARY TABLE tmp_t",
            false,
            &mut batch_effects,
        );
        assert!(
            batch_effects.may_have_uncommitted_work(),
            "DROP TEMPORARY TABLE must not be treated as an implicit commit"
        );

        SqlEditorWidget::mysql_batch_session_state_hint_for_sql(
            "GRANT SELECT ON db.* TO 'u'@'%'",
            false,
            &mut batch_effects,
        );
        assert!(
            !batch_effects.may_have_uncommitted_work(),
            "privilege changes are MySQL implicit-commit statements"
        );
    }

    #[test]
    fn mysql_batch_transaction_open_hints_apply_with_autocommit_on() {
        let mut batch_effects = crate::db::MySqlBatchSessionEffects::default();

        SqlEditorWidget::mysql_batch_session_state_hint_for_sql(
            "START TRANSACTION",
            true,
            &mut batch_effects,
        );
        assert!(
            batch_effects.may_have_uncommitted_work(),
            "START TRANSACTION opens a transaction even when autocommit is enabled"
        );

        SqlEditorWidget::mysql_batch_session_state_hint_for_sql(
            "ROLLBACK",
            true,
            &mut batch_effects,
        );
        assert!(!batch_effects.may_have_uncommitted_work());

        SqlEditorWidget::mysql_batch_session_state_hint_for_sql(
            "COMMIT AND CHAIN",
            true,
            &mut batch_effects,
        );
        assert!(
            batch_effects.may_have_uncommitted_work(),
            "COMMIT AND CHAIN starts the next transaction"
        );

        SqlEditorWidget::mysql_batch_session_state_hint_for_sql(
            "COMMIT AND NO CHAIN",
            true,
            &mut batch_effects,
        );
        assert!(
            !batch_effects.may_have_uncommitted_work(),
            "COMMIT AND NO CHAIN closes the current transaction without starting another"
        );
    }

