    #[test]
    fn mysql_single_statement_retained_state_uses_execution_autocommit_context() {
        let post_processor =
            crate::db::statement_session_post_processor_for(crate::db::DatabaseType::MySQL);
        let pending = crate::db::retained_session_state_after_statement(
            post_processor,
            RetainedSessionState::default(),
            post_processor.effects_for_sql("SET TRANSACTION ISOLATION LEVEL SERIALIZABLE"),
            false,
            false,
            false,
            false,
        );
        assert!(pending.may_have_transaction_mode_override());

        let select_effects = post_processor.effects_for_sql("SELECT 1");
        let autocommit_on_retained =
            SqlEditorWidget::mysql_retained_session_state_after_statement_from_probe(
                crate::db::DatabaseType::MySQL,
                pending,
                "SELECT 1",
                select_effects,
                true,
                false,
                crate::db::TransactionProbeResult {
                    may_have_uncommitted_work: false,
                    used_fallback: false,
                },
                false,
            );
        assert!(
            !autocommit_on_retained.may_have_transaction_mode_override(),
            "autocommit-on read statements should consume a pending SET TRANSACTION override"
        );
        assert_eq!(
            autocommit_on_retained.transaction_state(),
            TransactionSessionState::Clean
        );

        let autocommit_off_retained =
            SqlEditorWidget::mysql_retained_session_state_after_statement_from_probe(
                crate::db::DatabaseType::MySQL,
                pending,
                "SELECT 1",
                select_effects,
                false,
                false,
                crate::db::TransactionProbeResult {
                    may_have_uncommitted_work: true,
                    used_fallback: false,
                },
                false,
            );
        assert!(
            !autocommit_off_retained.may_have_transaction_mode_override(),
            "autocommit-off read transactions should consume the pending override"
        );
        assert_eq!(
            autocommit_off_retained.transaction_state(),
            TransactionSessionState::Clean
        );

        for sql in ["UPDATE t SET id = id", "SELECT * FROM t FOR UPDATE"] {
            let effects = post_processor.effects_for_sql(sql);
            let retained = SqlEditorWidget::mysql_retained_session_state_after_statement_from_probe(
                crate::db::DatabaseType::MySQL,
                RetainedSessionState::default(),
                sql,
                effects,
                false,
                false,
                crate::db::TransactionProbeResult {
                    may_have_uncommitted_work: true,
                    used_fallback: false,
                },
                false,
            );
            assert_eq!(
                retained.transaction_state(),
                TransactionSessionState::MaybeDirty,
                "{sql} must still keep commit/rollback state"
            );
        }
    }

