    fn mysql_success_requires_retained_session_when_prior_session_mode_survives_statement() {
        let post_processor =
            crate::db::statement_session_post_processor_for(crate::db::DatabaseType::MySQL);
        let session_mode_override = crate::db::retained_session_state_after_statement(
            post_processor,
            RetainedSessionState::default(),
            post_processor.effects_for_sql("SET SESSION TRANSACTION ISOLATION LEVEL SERIALIZABLE"),
            false,
            false,
            false,
            false,
        );
        let next_transaction_override = crate::db::retained_session_state_after_statement(
            post_processor,
            RetainedSessionState::default(),
            post_processor.effects_for_sql("SET TRANSACTION ISOLATION LEVEL SERIALIZABLE"),
            false,
            false,
            false,
            false,
        );
        let ddl_sql = "CREATE TABLE t (id INT)";
        let ddl_effects = crate::db::mysql_statement_session_effects_for_execution_context(
            ddl_sql,
            true,
            SqlEditorWidget::mysql_statement_session_effects_for_sql(ddl_sql),
        );

        assert!(
            SqlEditorWidget::mysql_success_requires_retained_session_after_action(
                DatabaseType::MySQL,
                session_mode_override,
                ddl_effects,
                true,
                false,
            ),
            "session-scope transaction mode survives implicit-commit DDL and must not be silently lost"
        );
        assert!(
            !SqlEditorWidget::mysql_success_requires_retained_session_after_action(
                DatabaseType::MySQL,
                next_transaction_override,
                ddl_effects,
                true,
                false,
            ),
            "next-transaction mode override is consumed by implicit-commit DDL"
        );

        let select_sql = "SELECT 1";
        let select_effects = crate::db::mysql_statement_session_effects_for_execution_context(
            select_sql,
            true,
            SqlEditorWidget::mysql_statement_session_effects_for_sql(select_sql),
        );
        assert!(
            SqlEditorWidget::mysql_success_requires_retained_session_after_action(
                DatabaseType::MySQL,
                session_mode_override,
                select_effects,
                true,
                false,
            ),
            "session-scope transaction mode survives autocommit-on reads"
        );
        assert!(
            !SqlEditorWidget::mysql_success_requires_retained_session_after_action(
                DatabaseType::MySQL,
                next_transaction_override,
                select_effects,
                true,
                false,
            ),
            "next-transaction mode override is consumed by an autocommit-on read"
        );
    }

    #[test]
    fn mysql_timeout_reset_failure_discards_clean_pooled_action_session() {
        let success: std::thread::Result<Result<(), String>> = Ok(Ok(()));
        let effects = SqlEditorWidget::mysql_statement_session_effects_for_sql("SELECT 1");

        assert_eq!(
            SqlEditorWidget::mysql_pooled_action_timeout_reset_failure_disposition(
                DatabaseType::MySQL,
                RetainedSessionState::default(),
                "SELECT 1",
                effects,
                true,
                false,
                &success,
            ),
            crate::db::RetainedSessionOutcome::DiscardPhysical,
        );
    }

    #[test]
    fn mysql_timeout_reset_failure_retains_dirty_prior_session_for_resolution() {
        let success: std::thread::Result<Result<(), String>> = Ok(Ok(()));
        let effects = SqlEditorWidget::mysql_statement_session_effects_for_sql("SELECT 1");
        let prior =
            RetainedSessionState::from_transaction_state(TransactionSessionState::MaybeDirty);

        let outcome = SqlEditorWidget::mysql_pooled_action_timeout_reset_failure_disposition(
            DatabaseType::MySQL,
            prior,
            "SELECT 1",
            effects,
            true,
            false,
            &success,
        );

        let crate::db::RetainedSessionOutcome::Retain(retained) = outcome else {
            panic!("dirty prior session must be retained for an explicit decision");
        };
        assert!(retained.requires_transaction_decision());
        assert!(
            crate::db::retained_session_transaction_resolution_should_discard_after_success(
                retained
            ),
            "timeout-reset-failed sessions must be discarded after commit/rollback resolution",
        );
    }

