    fn assert_mysql_live_result_routes(progress: &[QueryProgress]) {
        let progress_summary = summarize_progress(progress);
        assert_all_mysql_live_progress_routes_are_intended(progress, &progress_summary);

        let script_event = progress
            .iter()
            .find(|message| {
                matches!(
                    message,
                    QueryProgress::ScriptOutput { lines }
                        if lines.iter().any(|line| line.contains("MYSQL_ROUTE_SCRIPT"))
                )
            })
            .unwrap_or_else(|| {
                panic!("script output marker should be emitted\n{progress_summary}")
            });
        assert_script_result_routes_only(
            &progress_summary,
            "MySQL/MariaDB script transcript must route only to Script Output",
            script_event,
            &[ResultPaneRoute::ScriptOutput],
        );

        let grid_rows_event = progress
            .iter()
            .find(|message| {
                matches!(
                    message,
                    QueryProgress::Rows { rows, .. }
                        if rows.iter().flatten().any(|cell| cell == "MYSQL_ROUTE_GRID")
                )
            })
            .unwrap_or_else(|| panic!("grid marker row should be emitted\n{progress_summary}"));
        assert_script_result_routes_only(
            &progress_summary,
            "MySQL/MariaDB grid rows must route only to Data Grid",
            grid_rows_event,
            &[ResultPaneRoute::DataGrid],
        );

        let select_finished = progress
            .iter()
            .find(|message| {
                matches!(
                    message,
                    QueryProgress::StatementFinished { result, .. }
                        if result.sql.contains("MYSQL_ROUTE_GRID") && result.success
                )
            })
            .unwrap_or_else(|| {
                panic!("grid completion event should be emitted\n{progress_summary}")
            });
        assert_script_result_routes_only(
            &progress_summary,
            "MySQL/MariaDB SELECT completion must route only to Data Grid plus Messages Info",
            select_finished,
            &[ResultPaneRoute::DataGrid, ResultPaneRoute::MessagesInfo],
        );

        let dml_finished = progress
            .iter()
            .find(|message| {
                matches!(
                    message,
                    QueryProgress::StatementFinished { result, .. }
                        if result.sql.contains("INSERT INTO qt_result_route_monitor")
                            && result.success
                )
            })
            .unwrap_or_else(|| {
                panic!("non-select success event should be emitted\n{progress_summary}")
            });
        assert_script_result_routes_only(
            &progress_summary,
            "MySQL/MariaDB script non-select success must be owned by Script Output",
            dml_finished,
            &[],
        );

        let error_finished = progress
            .iter()
            .find(|message| {
                matches!(
                    message,
                    QueryProgress::StatementFinished { result, .. }
                        if result.sql.contains("qt_result_route_missing") && !result.success
                )
            })
            .unwrap_or_else(|| panic!("SQL error event should be emitted\n{progress_summary}"));
        assert_script_result_routes_only(
            &progress_summary,
            "MySQL/MariaDB SQL errors must route only to Messages Errors",
            error_finished,
            &[ResultPaneRoute::MessagesErrors],
        );

        assert!(
            !progress
                .iter()
                .any(|message| matches!(message, QueryProgress::DbmsOutput { .. })),
            "MySQL/MariaDB should not emit Oracle DBMS Output events\n{progress_summary}"
        );
    }

    fn assert_all_mysql_live_progress_routes_are_intended(
        progress: &[QueryProgress],
        progress_summary: &str,
    ) {
        for (event_index, message) in progress.iter().enumerate() {
            let routes = result_pane_routes_for_progress_with_script_context(message, true);
            let label = format!("event #{event_index}");
            match message {
                QueryProgress::Operation { progress, .. } => {
                    let nested_summary = summarize_progress(std::slice::from_ref(progress));
                    assert_all_mysql_live_progress_routes_are_intended(
                        std::slice::from_ref(progress),
                        &nested_summary,
                    );
                }
                QueryProgress::StatementOrigin { progress, .. } => {
                    let nested_summary = summarize_progress(std::slice::from_ref(progress));
                    assert_all_mysql_live_progress_routes_are_intended(
                        std::slice::from_ref(progress),
                        &nested_summary,
                    );
                }
                QueryProgress::OperationAbandoned { .. }
                | QueryProgress::OperationFinished { .. }
                | QueryProgress::CancelOutcome { .. } => {
                    assert!(routes.is_empty(), "{label}\n{progress_summary}")
                }
                QueryProgress::StatementStart { .. } => {
                    assert!(routes.is_empty(), "{label}\n{progress_summary}")
                }
                QueryProgress::SelectStart { .. }
                | QueryProgress::ResultEditMetadata { .. }
                | QueryProgress::Rows { .. }
                | QueryProgress::LazyFetchSession { .. }
                | QueryProgress::LazyFetchWaiting { .. }
                | QueryProgress::LazyFetchCanceling { .. }
                | QueryProgress::LazyFetchClosed { .. } => assert_eq!(
                    routes,
                    &[ResultPaneRoute::DataGrid],
                    "{label}\n{progress_summary}"
                ),
                QueryProgress::ScriptOutput { .. } => assert_eq!(
                    routes,
                    &[ResultPaneRoute::ScriptOutput],
                    "{label}\n{progress_summary}"
                ),
                QueryProgress::DbmsOutput { .. } => panic!(
                    "MySQL/MariaDB live monitor should not receive DBMS Output events: {label}\n{progress_summary}"
                ),
                QueryProgress::Message { kind, .. } => {
                    let expected = match kind {
                        ResultMessageKind::Info => ResultPaneRoute::MessagesInfo,
                        ResultMessageKind::Error => ResultPaneRoute::MessagesErrors,
                    };
                    assert_eq!(routes, &[expected], "{label}\n{progress_summary}");
                }
                QueryProgress::ExplainPlanOutput { .. } => assert_eq!(
                    routes,
                    &[ResultPaneRoute::DataGrid],
                    "{label}\n{progress_summary}"
                ),
                QueryProgress::StatementFinished { result, .. } => {
                    let expected: &[ResultPaneRoute] =
                        if result.is_select && result.success && !result.message.trim().is_empty()
                        {
                            &[ResultPaneRoute::DataGrid, ResultPaneRoute::MessagesInfo]
                        } else if result.is_select && result.success {
                            &[ResultPaneRoute::DataGrid]
                        } else if !result.success && !result.message.trim().is_empty() {
                            &[ResultPaneRoute::MessagesErrors]
                        } else {
                            &[]
                        };
                    assert_eq!(routes, expected, "{label}\n{progress_summary}");
                }
                QueryProgress::StatementCancelledHistory { .. }
                | QueryProgress::BatchStart { .. }
                | QueryProgress::PromptInput { .. }
                | QueryProgress::RequestCancelOldestLazyFetchForSessionPool { .. }
                | QueryProgress::NotifyCancelOldestLazyFetchForSessionPool
                | QueryProgress::LazyFetchCancelFailed { .. }
                | QueryProgress::AutoCommitChanged { .. }
                | QueryProgress::TransactionModeChanged { .. }
                | QueryProgress::TransactionActionFinished
                | QueryProgress::ConnectionChanged { .. }
                | QueryProgress::ScopeChangedNotice { .. }
                | QueryProgress::WorkerPanicked { .. }
                | QueryProgress::ExecutionAbandoned { .. }
                | QueryProgress::ExecutionFinished(_)
                | QueryProgress::BatchFinished
                | QueryProgress::MetadataRefreshNeeded => assert!(
                    routes.is_empty(),
                    "{label}\n{progress_summary}"
                ),
            }
        }
    }

    fn assert_mysql_live_explain_routes_only_to_explain_plan(db_type: DatabaseType) {
        let Some(mut connection) =
            mysql_test_connection_with_mode_for_db_type(TransactionMode::default(), db_type)
        else {
            return;
        };
        let conn = connection
            .get_mysql_connection_mut()
            .expect("MySQL/MariaDB route monitor should expose a live connection");
        let plan =
            crate::db::query::mysql_executor::MysqlExecutor::get_explain_plan(conn, "SELECT 1")
                .expect("MySQL/MariaDB explain route monitor should succeed");
        let explain_event = QueryProgress::ExplainPlanOutput {
            result: SqlEditorWidget::build_explain_plan_result(
                &crate::ui::explain_plan::ExplainPlanData::Flat {
                    columns: plan
                        .columns
                        .iter()
                        .map(|column| column.name.clone())
                        .collect(),
                    rows: plan.rows.clone(),
                },
            ),
        };
        assert_result_routes_only(
            "MySQL/MariaDB explain progress",
            "MySQL/MariaDB explain output must route to Data Grid as a new explain tab",
            &explain_event,
            &[ResultPaneRoute::DataGrid],
        );
    }

    fn drain_mysql_progress(receiver: mpsc::Receiver<QueryProgress>) -> Vec<QueryProgress> {
        drain_mysql_progress_with_idle_timeout(receiver, Duration::from_millis(50))
    }

    fn drain_mysql_progress_with_idle_timeout(
        receiver: mpsc::Receiver<QueryProgress>,
        progress_idle_timeout: Duration,
    ) -> Vec<QueryProgress> {
        let mut progress = Vec::new();
        let mut wait = Duration::from_secs(5);
        while let Ok(message) = receiver.recv_timeout(wait) {
            progress.push(message);
            wait = progress_idle_timeout;
        }
        progress
    }

    fn assert_mysql_batch_script_reaches_final_status_pass(script: &str, db_activity: &str) {
        assert_mysql_batch_script_reaches_final_status_pass_for_db_type(
            script,
            db_activity,
            DatabaseType::MySQL,
        );
    }

    fn assert_mysql_batch_script_reaches_final_status_pass_for_db_type(
        script: &str,
        db_activity: &str,
        db_type: DatabaseType,
    ) {
        let Some(host) = mysql_test_env("SPACE_QUERY_TEST_MYSQL_HOST") else {
            eprintln!("skipping: SPACE_QUERY_TEST_MYSQL_HOST is not set");
            return;
        };
        let Some(database) = mysql_test_env("SPACE_QUERY_TEST_MYSQL_DATABASE") else {
            eprintln!("skipping: SPACE_QUERY_TEST_MYSQL_DATABASE is not set");
            return;
        };
        let Some(user) = mysql_test_env("SPACE_QUERY_TEST_MYSQL_USER") else {
            eprintln!("skipping: SPACE_QUERY_TEST_MYSQL_USER is not set");
            return;
        };
        let Some(password) = mysql_test_env("SPACE_QUERY_TEST_MYSQL_PASSWORD") else {
            eprintln!("skipping: SPACE_QUERY_TEST_MYSQL_PASSWORD is not set");
            return;
        };
        let port = mysql_test_env("SPACE_QUERY_TEST_MYSQL_PORT")
            .and_then(|value| value.parse::<u16>().ok())
            .unwrap_or(3306);

        let mut connection = DatabaseConnection::new();
        connection
            .set_auto_commit(true)
            .expect("set initial MySQL/MariaDB auto-commit");
        connection
            .connect(ConnectionInfo::new_with_type(
                "MYSQL_TEST",
                &user,
                &password,
                &host,
                port,
                &database,
                db_type,
            ))
            .expect("MySQL regression test connection should succeed");

        let shared_connection = Arc::new(Mutex::new(connection));
        let session = Arc::new(Mutex::new(SessionState {
            db_type,
            ..SessionState::default()
        }));
        let current_mysql_cancel_context: Arc<Mutex<Option<MySqlQueryCancelContext>>> =
            Arc::new(Mutex::new(None));
        let current_query_cancel_handle: Arc<Mutex<OperationCancelTarget>> =
            Arc::new(Mutex::new(OperationCancelTarget::default()));
        let pooled_db_session = crate::db::SharedDbSessionLease::new();
        let tab_auto_commit_override = Arc::new(Mutex::new(None));
        let tab_transaction_mode_override: Arc<Mutex<Option<crate::db::TransactionMode>>> =
            Arc::new(Mutex::new(None));
        let active_lazy_fetch: Arc<Mutex<Option<LazyFetchHandle>>> = Arc::new(Mutex::new(None));
        let next_lazy_fetch_session_id = Arc::new(AtomicU64::new(1));
        let cancel_flag = Arc::new(Mutex::new(false));
        let (sender, receiver) = super::test_query_progress_channel();

        SqlEditorWidget::execute_mysql_batch(
            &shared_connection,
            &TabConnectionBinding::unbound(),
            0,
            &sender,
            db_type,
            script,
            "MYSQL_TEST",
            &session,
            &pooled_db_session,
            &tab_auto_commit_override,
            &tab_transaction_mode_override,
            &active_lazy_fetch,
            &next_lazy_fetch_session_id,
            &current_mysql_cancel_context,
            &current_query_cancel_handle,
            &cancel_flag,
            true,
            None,
            None,
            crate::utils::DEFAULT_LAZY_FETCH_BATCH_SIZE as usize,
            true,
            crate::db::TransactionMode::default(),
            db_activity,
            None,
            None,
            None,
            0,
            None,
        );
        drop(sender);

        let progress = drain_mysql_progress(receiver);
        let progress_summary = summarize_progress(&progress);
        let final_status_index = progress.iter().find_map(|message| match message {
            QueryProgress::StatementFinished { index, result, .. }
                if result.sql.contains("'FINAL_STATUS' AS section_name") =>
            {
                Some(*index)
            }
            _ => None,
        });

        assert!(
            progress.iter().any(|message| matches!(
                message,
                QueryProgress::AutoCommitChanged { enabled: false }
            )),
            "@TRANSACTION should disable autocommit during batch execution\n{progress_summary}"
        );
        assert!(
            final_status_index.is_some(),
            "batch execution should emit the FINAL_STATUS select\n{progress_summary}"
        );
        assert!(
            progress
                .iter()
                .any(|message| match (final_status_index, message) {
                    (
                        Some(index),
                        QueryProgress::Rows {
                            index: row_index,
                            rows,
                        },
                    ) if *row_index == index => {
                        rows.iter().any(|row| row.iter().any(|cell| cell == "PASS"))
                    }
                    _ => false,
                }),
            "batch execution should reach the FINAL_STATUS PASS result\n{progress_summary}"
        );
    }

