    #[test]
    #[ignore = "requires local MySQL or MariaDB test database via SPACE_QUERY_TEST_MYSQL_* env vars"]
    fn mysql_pooled_session_applies_global_database_to_clean_retained_session() {
        let Some(harness) = MysqlSessionRuleHarness::new(true) else {
            return;
        };

        let setup_progress = harness.execute(
            "\
USE information_schema;
SET @qt_tab_session_database = DATABASE();
SELECT 'SETUP_STATUS' AS section_name,
       CASE
           WHEN @qt_tab_session_database = 'information_schema' THEN 'PASS'
           ELSE CONCAT('FAIL database=', COALESCE(@qt_tab_session_database, '<null>'))
       END AS result_status;
",
            "mysql tab database retention setup",
        );
        assert_no_failed_mysql_statement(&setup_progress);

        harness.switch_primary_database_to_initial();

        let expected_database = harness.initial_database.replace('\'', "''");
        let verify_sql = format!(
            "\
SET @qt_tab_session_probe = @qt_tab_session_database;
SELECT 'FINAL_STATUS' AS section_name,
       CASE
           WHEN DATABASE() = '{expected_database}'
                AND @qt_tab_session_database = 'information_schema'
           THEN 'PASS'
           ELSE CONCAT(
               'FAIL database=', COALESCE(DATABASE(), '<null>'),
               ', var=', COALESCE(@qt_tab_session_database, '<null>')
           )
       END AS result_status;
"
        );
        let verify_progress = harness.execute(
            &verify_sql,
            "mysql global database propagation verification",
        );

        assert_no_failed_mysql_statement(&verify_progress);
        assert_mysql_final_status_pass(&verify_progress);
        harness.pooled_db_session.clear();
    }

    #[test]
    #[ignore = "requires local MySQL or MariaDB test database via SPACE_QUERY_TEST_MYSQL_* env vars"]
    fn mysql_pooled_session_applies_global_database_to_dirty_retained_session() {
        let Some(harness) = MysqlSessionRuleHarness::new(true) else {
            return;
        };
        if harness
            .initial_database
            .trim()
            .eq_ignore_ascii_case("information_schema")
        {
            eprintln!("skipping: test requires a writable initial database");
            return;
        }

        let setup_progress = harness.execute(
            "\
DROP TABLE IF EXISTS qt_pool_scope_dirty;
CREATE TABLE qt_pool_scope_dirty (id INT PRIMARY KEY);
@TRANSACTION
INSERT INTO qt_pool_scope_dirty VALUES (1);
USE information_schema;
SET @qt_tab_session_database = DATABASE();
SELECT 'SETUP_STATUS' AS section_name,
       CASE
           WHEN @qt_tab_session_database = 'information_schema' THEN 'PASS'
           ELSE CONCAT('FAIL database=', COALESCE(@qt_tab_session_database, '<null>'))
       END AS result_status;
",
            "mysql dirty tab database retention setup",
        );
        assert_no_failed_mysql_statement(&setup_progress);

        harness.switch_primary_database_to_initial();

        let expected_database = harness.initial_database.replace('\'', "''");
        let verify_sql = format!(
            "\
SELECT 'FINAL_STATUS' AS section_name,
       CASE
           WHEN DATABASE() = '{expected_database}'
                AND @qt_tab_session_database = 'information_schema'
                AND (SELECT COUNT(*) FROM qt_pool_scope_dirty) = 1
           THEN 'PASS'
           ELSE CONCAT(
               'FAIL database=', COALESCE(DATABASE(), '<null>'),
               ', var=', COALESCE(@qt_tab_session_database, '<null>')
           )
       END AS result_status;
"
        );
        let verify_progress = harness.execute(
            &verify_sql,
            "mysql dirty global database propagation verification",
        );
        assert_no_failed_mysql_statement(&verify_progress);
        assert_mysql_final_status_pass(&verify_progress);

        let cleanup_progress = harness.execute(
            "ROLLBACK; DROP TABLE IF EXISTS qt_pool_scope_dirty;",
            "mysql dirty global database propagation cleanup",
        );
        assert_no_failed_mysql_statement(&cleanup_progress);
        harness.pooled_db_session.clear();
    }

    #[test]
    #[ignore = "requires local MySQL or MariaDB test database via SPACE_QUERY_TEST_MYSQL_* env vars"]
    fn mysql_pooled_session_preserves_complex_session_state_until_commit() {
        let script = "\
DROP PROCEDURE IF EXISTS qt_session_rule_call;
DROP TABLE IF EXISTS qt_session_rule_result;
CREATE TABLE qt_session_rule_result (id INT PRIMARY KEY, note VARCHAR(64));
DELIMITER //
CREATE PROCEDURE qt_session_rule_call()
BEGIN
    INSERT INTO qt_session_rule_result (id, note) VALUES (3, 'call');
END//
DELIMITER ;
@TRANSACTION
CREATE TEMPORARY TABLE tmp_qt_session_rule (id INT PRIMARY KEY);
INSERT INTO tmp_qt_session_rule VALUES (1);
SET @qt_session_rule_note = 'session-var';
SELECT COUNT(*)
INTO @qt_session_rule_count
FROM tmp_qt_session_rule;
SET @qt_session_rule_sql = 'INSERT INTO tmp_qt_session_rule VALUES (2)';
PREPARE qt_session_rule_stmt FROM @qt_session_rule_sql;
EXECUTE qt_session_rule_stmt;
DEALLOCATE PREPARE qt_session_rule_stmt;
CALL qt_session_rule_call();
INSERT INTO qt_session_rule_result
SELECT id, @qt_session_rule_note
FROM tmp_qt_session_rule;
COMMIT;
SELECT 'FINAL_STATUS' AS section_name,
       CASE
           WHEN COUNT(*) = 3
                AND SUM(note = 'session-var') = 2
                AND SUM(note = 'call') = 1
                AND @qt_session_rule_count = 1
           THEN 'PASS'
           ELSE CONCAT('FAIL count=', COUNT(*), ', session_count=', COALESCE(@qt_session_rule_count, -1))
       END AS result_status
FROM qt_session_rule_result;
DROP PROCEDURE IF EXISTS qt_session_rule_call;
DROP TABLE IF EXISTS qt_session_rule_result;
";
        let Some((progress, pooled_db_session)) = execute_mysql_session_rule_script(
            script,
            true,
            "mysql complex session retention regression",
        ) else {
            return;
        };

        assert_no_failed_mysql_statement(&progress);
        assert_mysql_final_status_pass(&progress);
        let snapshot = pooled_db_session.snapshot().expect(
            "session-scoped state should keep the tab pooled session after selected range execution",
        );
        assert_eq!(snapshot.db_type, DatabaseType::MySQL);
        assert!(
            !snapshot.retained_state.may_have_uncommitted_work()
                && !snapshot.retained_state.may_hold_session_lock(),
            "committed script should not be marked as transaction or lock state\n{}",
            summarize_progress(&progress)
        );
        pooled_db_session.clear();
    }

