    #[test]
    #[ignore = "requires local Oracle listener"]
    fn oracle_thin_query_tool_dynamic_ddl_cleanup_drops_table() {
        let _oracle_schema_guard = oracle_thin_shared_schema_test_guard();
        let mut conn =
            tns_thin::OracleThinSession::connect(oracle_thin_live_config()).expect("thin login");
        SqlEditorWidget::ensure_oracle_thin_runtime(&mut conn).expect("install runtime");
        let _ = SqlEditorWidget::execute_oracle_thin_statement(
            &mut conn,
            "DROP TABLE qt_dept CASCADE CONSTRAINTS PURGE",
            false,
        );
        SqlEditorWidget::execute_oracle_thin_statement(
            &mut conn,
            "CREATE TABLE qt_dept (dept_id NUMBER)",
            false,
        )
        .expect("create qt_dept");
        SqlEditorWidget::execute_oracle_thin_statement(
            &mut conn,
            "BEGIN
                FOR r IN (
                    SELECT object_name, object_type
                    FROM user_objects
                    WHERE object_name IN ('QT_DEPT')
                ) LOOP
                    BEGIN
                        IF r.object_type = 'TABLE' THEN
                            EXECUTE IMMEDIATE 'DROP TABLE ' || r.object_name || ' CASCADE CONSTRAINTS PURGE';
                        END IF;
                    EXCEPTION
                        WHEN OTHERS THEN
                            NULL;
                    END;
                END LOOP;
            END;",
            false,
        )
        .expect("cleanup block");

        let (_columns, rows) = SqlEditorWidget::oracle_thin_select_cells(
            &mut conn,
            "SELECT COUNT(*) FROM user_objects WHERE object_name = 'QT_DEPT'",
        )
        .expect("count qt_dept");
        assert_eq!(rows[0][0], "0");
    }

