    #[ignore = "requires local Oracle listener and executes every formatted test fixture"]
    fn oracle_thin_query_tool_runs_all_formatted_fixture_scripts_without_errors() {
        for layout in [SqlCommaListLayout::Wrapped, SqlCommaListLayout::Stacked] {
            oracle_thin_query_tool_runs_all_formatted_fixture_scripts_for_layout(layout);
        }
    }

    fn oracle_thin_query_tool_runs_all_formatted_fixture_scripts_for_layout(
        layout: SqlCommaListLayout,
    ) {
        let mut format_config = AppConfig::new();
        format_config.sql_comma_list_layout = layout;
        let mut fixture_paths = std::fs::read_dir("test")
            .expect("read Oracle fixture directory")
            .filter_map(Result::ok)
            .map(|entry| entry.path())
            .filter(|path| {
                path.extension()
                    .and_then(|extension| extension.to_str())
                    .is_some_and(|extension| matches!(extension, "sql" | "txt"))
            })
            .collect::<Vec<_>>();
        fixture_paths.sort();
        assert_eq!(fixture_paths.len(), 43, "Oracle fixture inventory changed");

        let mut audit_failures = Vec::new();
        for path in fixture_paths {
            let source = std::fs::read_to_string(&path)
                .unwrap_or_else(|err| panic!("read {}: {err}", path.display()));
            let formatted = SqlEditorWidget::format_for_auto_formatting_with_config(
                &source,
                false,
                Some(DatabaseType::Oracle),
                &format_config,
            );
            let formatted = oracle_thin_skip_unsupported_implicit_invocations(&formatted);
            let progress = oracle_thin_run_script_with_auto_commit(&formatted, false);
            let failures = oracle_thin_progress_failures(&progress);
            let successful_statements = progress
                .iter()
                .filter(|event| {
                    matches!(
                        event,
                        QueryProgress::StatementFinished { result, .. } if result.success
                    )
                })
                .count();

            if successful_statements == 0 {
                audit_failures.push(format!(
                    "{}: no successful statement was emitted",
                    path.display()
                ));
            }
            audit_failures.extend(
                failures
                    .into_iter()
                    .map(|failure| format!("{}: {failure}", path.display())),
            );
            eprintln!(
                "{layout:?} formatted live fixture checked: {} ({successful_statements} successful statements)",
                path.display()
            );
        }

        assert!(
            audit_failures.is_empty(),
            "{layout:?} formatted Oracle fixture execution failures:\n{}",
            audit_failures.join("\n")
        );
    }

    #[test]
    #[ignore = "requires local Oracle listener"]
    fn oracle_thin_lazy_fetch_help_join_emits_grid_batches() {
        let sql = "select * from help a join help b on 1=1";
        let progress = oracle_lazy_worker_progress_for_sql(OracleDriverMode::Thin, sql, 25, false);
        let failures = oracle_thin_progress_failures(&progress);
        let snapshot = oracle_grid_snapshot(&progress);

        assert!(
            failures.is_empty(),
            "Oracle Thin lazy failures: {failures:?}"
        );
        assert!(
            progress
                .iter()
                .any(|event| matches!(event, QueryProgress::LazyFetchSession { .. })),
            "Thin should create a lazy fetch session"
        );
        assert!(
            progress
                .iter()
                .any(|event| matches!(event, QueryProgress::LazyFetchWaiting { .. })),
            "Thin should pause after the initial grid batch"
        );
        assert!(
            progress
                .iter()
                .any(|event| matches!(event, QueryProgress::LazyFetchClosed { .. })),
            "Thin should close the lazy cursor after lazy fetch commands"
        );
        let initial_batch_len = progress
            .iter()
            .find_map(|event| match event {
                QueryProgress::Rows { rows, .. } => Some(rows.len()),
                _ => None,
            })
            .unwrap_or_default();
        assert!(
            initial_batch_len <= 25,
            "initial Thin lazy batch should not fetch the full result: {initial_batch_len}"
        );
        assert!(!snapshot.columns.is_empty(), "datagrid should have columns");
        assert!(!snapshot.rows.is_empty(), "datagrid should have rows");
        assert!(
            snapshot.rows.len() > initial_batch_len,
            "FetchMore should append rows after the initial lazy batch"
        );
    }

    #[test]
    #[ignore = "requires local Oracle listener"]
    fn oracle_thin_lazy_fetch_cancel_reports_the_statement_for_query_history() {
        // A cancelled lazy fetch closes through LazyFetchClosed and emits no
        // StatementFinished, so query history only keeps the statement if the
        // worker reports it through the history-only event.
        let sql = "select * from help a join help b on 1=1";
        let progress = oracle_lazy_worker_progress_for_sql(OracleDriverMode::Thin, sql, 25, false);

        let (history_sql, history_rows) = progress
            .iter()
            .find_map(|event| match event {
                QueryProgress::StatementCancelledHistory { sql, row_count, .. } => {
                    Some((sql.clone(), *row_count))
                }
                _ => None,
            })
            .expect("cancelled lazy fetch should report the statement for query history");
        assert_eq!(history_sql, sql);
        assert!(
            history_rows > 0,
            "history entry should keep the rows fetched before the cancel"
        );
        assert!(
            !progress
                .iter()
                .any(|event| matches!(event, QueryProgress::StatementFinished { .. })),
            "a cancelled lazy fetch must not also report a finished statement"
        );

        // A lazy fetch that runs to EOF already reports through
        // StatementFinished, so it must not add a second history entry.
        let completed = oracle_lazy_worker_progress_for_sql(OracleDriverMode::Thin, sql, 25, true);
        assert!(
            !completed
                .iter()
                .any(|event| matches!(event, QueryProgress::StatementCancelledHistory { .. })),
            "a completed lazy fetch must not report a cancelled statement"
        );
    }

    #[test]
    #[ignore = "requires local Oracle listener"]
    fn oracle_thin_lazy_fetch_clob_emits_initial_batch_before_waiting() {
        // CLOB columns make the initial execute run without prefetch (define
        // fetch), so the worker itself must fetch the first batch; otherwise
        // the grid sits at 0 rows in the lazy-waiting state.
        let sql = "select topic, seq, to_clob(info) info_clob from help";
        let progress = oracle_lazy_worker_progress_for_sql(OracleDriverMode::Thin, sql, 25, false);
        let failures = oracle_thin_progress_failures(&progress);
        assert!(
            failures.is_empty(),
            "Oracle Thin CLOB lazy failures: {failures:?}"
        );
        let first_waiting = progress
            .iter()
            .position(|event| matches!(event, QueryProgress::LazyFetchWaiting { .. }))
            .expect("Thin should pause after the initial CLOB grid batch");
        let first_rows = progress
            .iter()
            .position(|event| matches!(event, QueryProgress::Rows { .. }))
            .expect("CLOB lazy select should emit an initial grid batch without any FetchMore");
        assert!(
            first_rows < first_waiting,
            "initial CLOB batch must reach the grid before the lazy-waiting state \
             (rows event at {first_rows}, waiting at {first_waiting})"
        );
        let initial_batch_len = progress
            .iter()
            .find_map(|event| match event {
                QueryProgress::Rows { rows, .. } => Some(rows.len()),
                _ => None,
            })
            .unwrap_or_default();
        assert!(
            (1..=25).contains(&initial_batch_len),
            "initial CLOB lazy batch should hold up to one batch of rows: {initial_batch_len}"
        );
    }

