    #[test]
    #[ignore = "requires local Oracle listener"]
    fn oracle_thin_protocol_318_fv12_lazy_fetch_all_large_result_completes_under_one_second() {
        if oracle_thin_skip_unless_requested_protocol(
            318,
            "oracle_thin_protocol_318_fv12_lazy_fetch_all_large_result_completes_under_one_second",
        ) {
            return;
        }
        let sql = "select level as n, mod(level, 10) as bucket from dual connect by level <= 20050";
        let config = oracle_thin_live_config_with_protocol(318, 12);
        let caps_conn =
            tns_thin::OracleThinSession::connect(config.clone()).expect("thin 318/FV12 login");
        assert_oracle_thin_protocol_318_fv12_no_eor(&caps_conn);
        drop(caps_conn);

        let run = oracle_lazy_worker_run_for_sql_with_config_and_drive(
            OracleDriverMode::Thin,
            sql,
            250,
            OracleLazyFetchDrive::FetchAll,
            Some(config),
        );
        let failures = oracle_thin_progress_failures(&run.events);
        let snapshot = oracle_grid_snapshot(&run.events);
        let finished_rows = run.events.iter().find_map(|event| match event {
            QueryProgress::StatementFinished { result, .. } if result.success => {
                Some(result.row_count)
            }
            _ => None,
        });
        let row_batches = run
            .events
            .iter()
            .filter(|event| matches!(event, QueryProgress::Rows { .. }))
            .count();
        let fetch_all_elapsed = run
            .fetch_all_elapsed
            .expect("FetchAll drive should capture elapsed time");

        assert!(
            failures.is_empty(),
            "Oracle Thin 318/FV12 generated-row one-click FetchAll failures: {failures:?}"
        );
        assert!(
            row_batches >= 4,
            "one-click FetchAll must report multiple progress batches; events={}",
            run.events.len()
        );
        assert_eq!(
            snapshot.rows.len(),
            20_050,
            "318/FV12 one-click FetchAll should fetch all generated rows"
        );
        assert_eq!(
            finished_rows,
            Some(20_050),
            "318/FV12 one-click FetchAll feedback should report all rows"
        );
        eprintln!("318/FV12 one-click FetchAll elapsed: {fetch_all_elapsed:?}");
        assert!(
            fetch_all_elapsed < Duration::from_secs(1),
            "318/FV12 one-click FetchAll should complete within 1s, elapsed={fetch_all_elapsed:?}"
        );
    }

    #[test]
