    #[test]
    #[ignore = "requires local Oracle listener"]
    fn oracle_thin_protocol_318_fv12_lazy_fetch_more_ui_path_reaches_direct_row_count() {
        if oracle_thin_skip_unless_requested_protocol(
            318,
            "oracle_thin_protocol_318_fv12_lazy_fetch_more_ui_path_reaches_direct_row_count",
        ) {
            return;
        }
        let sql = "select * from help";
        let config = oracle_thin_live_config_with_protocol(318, 12);
        let mut direct =
            tns_thin::OracleThinSession::connect(config.clone()).expect("thin 318/FV12 login");
        assert_oracle_thin_protocol_318_fv12_no_eor(&direct);
        direct
            .set_call_timeout(Some(Duration::from_secs(30)))
            .expect("set direct fetch timeout");
        let direct_rows = direct
            .query_described_fetch_all(sql, 100)
            .expect("direct 318/FV12 HELP fetch all")
            .result
            .rows
            .len();
        assert!(
            direct_rows > 100,
            "test must require at least one lazy FetchMore after the initial batch"
        );

        let progress = oracle_lazy_worker_progress_for_sql_with_config_and_drive(
            OracleDriverMode::Thin,
            sql,
            100,
            OracleLazyFetchDrive::FetchMoreUntilFinished,
            Some(config),
        );
        let failures = oracle_thin_progress_failures(&progress);
        let snapshot = oracle_grid_snapshot(&progress);
        let finished_rows = progress.iter().find_map(|event| match event {
            QueryProgress::StatementFinished { result, .. } if result.success => {
                Some(result.row_count)
            }
            _ => None,
        });
        let waiting_count = progress
            .iter()
            .filter(|event| matches!(event, QueryProgress::LazyFetchWaiting { .. }))
            .count();

        assert!(
            failures.is_empty(),
            "Oracle Thin 318/FV12 lazy FetchMore failures: {failures:?}"
        );
        assert!(
            waiting_count > 1,
            "318/FV12 UI path must drive repeated FetchMore commands; events={}",
            progress.len()
        );
        assert_eq!(
            snapshot.rows.len(),
            direct_rows,
            "318/FV12 UI lazy fetch should reach the direct fetch-all row count"
        );
        assert_eq!(
            finished_rows,
            Some(direct_rows),
            "318/FV12 statement feedback should report the fetched HELP row count"
        );
    }

    #[test]
    #[ignore = "requires local Oracle listener"]
    fn oracle_thin_lazy_fetch_cancel_during_fetch_all_closes_without_cleanup_error() {
        let sql = "select a.object_id from all_objects a, all_objects b, all_objects c";
        let started = Instant::now();
        let progress = oracle_thin_lazy_fetch_cancel_during_fetch_all_progress(sql, 1);
        let elapsed = started.elapsed();
        let failures = oracle_thin_progress_failures(&progress);
        let close_events = progress
            .iter()
            .filter_map(|event| match event {
                QueryProgress::LazyFetchClosed {
                    cancelled,
                    cursor_closed,
                    fetch_worker_done,
                    error_kind,
                    ..
                } => Some(format!(
                    "cancelled={cancelled} cursor_closed={cursor_closed} fetch_worker_done={fetch_worker_done} error_kind={error_kind:?}"
                )),
                _ => None,
            })
            .collect::<Vec<_>>();

        assert!(
            elapsed < Duration::from_secs(5),
            "Oracle Thin lazy cancel should close promptly; elapsed={elapsed:?} events={}",
            progress.len()
        );
        assert!(
            failures.is_empty(),
            "Oracle Thin lazy cancel failures: {failures:?}"
        );
        assert!(
            progress.iter().any(|event| {
                matches!(
                    event,
                    QueryProgress::LazyFetchClosed {
                        cancelled: true,
                        cursor_closed: false,
                        fetch_worker_done: true,
                        error_kind: InterruptKind::Cancelled,
                        ..
                    }
                )
            }),
            "Thin lazy cancel should close as cancelled; events={} close_events={close_events:?}",
            progress.len()
        );
        assert!(
            !progress.iter().any(|event| matches!(
                event,
                QueryProgress::StatementFinished { result, .. }
                    if result.message.to_ascii_lowercase().contains("invalid utf-8")
            )),
            "cleanup must not surface invalid UTF-8 parse errors; events={}",
            progress.len()
        );
    }

